        'Resposta da passagem': 'Antwort der Passage',
        'A resposta recebida reconheceu o ensinamento central.': 'Die erhaltene Antwort erkannte die zentrale Lehre.',
        'A resposta recebida abriu uma retomada; a explicação ajuda a aproximar o sentido.': 'Die erhaltene Antwort eröffnet eine erneute Betrachtung; die Erklärung hilft, dem Sinn näherzukommen.',
        'explicação inscrita': 'Erklärung eingetragen',
