const CHALLENGE_CONTENT_TRANSLATIONS = {
    es: {
        'Durante a cópia de Gênesis 12, um aprendiz observa que Abrão parte sem conhecer todo o destino e pergunta o que essa cena ensina sobre a fé.': 'Durante la copia de Génesis 12, un aprendiz observa que Abrán parte sin conocer todo el destino y pregunta qué enseña esta escena sobre la fe.',
        'Qual leitura preserva melhor o sentido da passagem?': '¿Qué lectura conserva mejor el sentido del pasaje?',
        'A fé é uma viagem sem direção, porque Deus não oferece promessa alguma.': 'La fe es un viaje sin dirección, porque Dios no ofrece ninguna promesa.',
        'A fé responde ao chamado e caminha confiando numa promessa que ainda não está totalmente visível.': 'La fe responde al llamado y camina confiando en una promesa que aún no es completamente visible.',
        'A passagem ensina que obedecer exige abandonar todos os vínculos familiares para sempre.': 'El pasaje enseña que obedecer exige abandonar para siempre todos los vínculos familiares.',
        'O chamado vale apenas como uma ordem antiga, sem relação com confiança e resposta hoje.': 'El llamado solo vale como una orden antigua, sin relación con la confianza y la respuesta de hoy.',
        'Quando a fé dá o primeiro passo': 'Cuando la fe da el primer paso',
        'Interpretar uma passagem é relacionar a ordem recebida à resposta concreta de Abrão: a fé não é desorientação nem isolamento, mas confiança que se põe a caminho.': 'Interpretar un pasaje es relacionar la orden recibida con la respuesta concreta de Abrán: la fe no es desorientación ni aislamiento, sino confianza que se pone en camino.',
        'A leitura mais coerente entende a fé como uma resposta confiante ao chamado: Abrão parte porque há uma promessa, mesmo que o caminho completo ainda não tenha sido mostrado.': 'La lectura más coherente entiende la fe como una respuesta confiada al llamado: Abrán parte porque hay una promesa, aunque el camino completo todavía no haya sido mostrado.',
        'Em Gênesis 12:1-4, Deus ordena que Abrão saia de sua terra e, ao mesmo tempo, anuncia bênção e futuro. O movimento da passagem une chamado, promessa e partida; por isso, não se trata de caminhar sem direção, mas de confiar antes de possuir todas as respostas.': 'En Génesis 12:1-4, Dios ordena a Abrán salir de su tierra y, al mismo tiempo, anuncia bendición y futuro. El movimiento del pasaje une llamado, promesa y partida; por eso, no se trata de caminar sin dirección, sino de confiar antes de tener todas las respuestas.',
        'Ao copiar a cena do mar Vermelho, um aprendiz pergunta se o silêncio pedido por Moisés significa desistir de agir ou confiar diante do medo.': 'Al copiar la escena del mar Rojo, un aprendiz pregunta si el silencio pedido por Moisés significa dejar de actuar o confiar ante el miedo.',
        'Qual leitura preserva melhor o ensinamento de Êxodo 14:14?': '¿Qué lectura conserva mejor la enseñanza de Éxodo 14:14?',
        'O povo deveria abandonar toda responsabilidade, porque a fé torna qualquer ação humana desnecessária.': 'El pueblo debería abandonar toda responsabilidad, porque la fe hace innecesaria cualquier acción humana.',
        'Moisés convida o povo a reconhecer a ação de Deus e a atravessar com confiança, não a permanecer para sempre imóvel.': 'Moisés invita al pueblo a reconocer la acción de Dios y a cruzar con confianza, no a permanecer inmóvil para siempre.',
        'O versículo promete que pessoas fiéis nunca mais enfrentarão ameaças ou situações assustadoras.': 'El versículo promete que las personas fieles nunca volverán a enfrentar amenazas o situaciones aterradoras.',
        'A passagem ensina que o medo deve ser escondido e que perguntas em momentos de crise são sempre falta de fé.': 'El pasaje enseña que el miedo debe ocultarse y que las preguntas en momentos de crisis siempre son falta de fe.',
        'Silêncio que prepara a travessia': 'Silencio que prepara el cruce',
        'A confiança diante do mar não elimina a travessia: ela interrompe o pânico para que o povo reconheça o cuidado de Deus e avance quando o caminho se abre.': 'La confianza ante el mar no elimina el cruce: interrumpe el pánico para que el pueblo reconozca el cuidado de Dios y avance cuando el camino se abra.',
        'A leitura mais coerente entende o silêncio como uma pausa de confiança diante do medo, que prepara Israel para seguir a orientação de Deus e atravessar.': 'La lectura más coherente entiende el silencio como una pausa de confianza ante el miedo, que prepara a Israel para seguir la orientación de Dios y cruzar.',
        'Êxodo 14:10-16 mostra Israel encurralado, temeroso e questionando Moisés. A palavra “O Senhor pelejará por vós” não encerra a narrativa em passividade: logo depois, Moisés recebe a ordem de mandar o povo avançar. O contexto une confiança e movimento.': 'Éxodo 14:10-16 muestra a Israel acorralado, temeroso y cuestionando a Moisés. La palabra «El Señor luchará por vosotros» no termina la narración en pasividad: poco después, Moisés recibe la orden de hacer avanzar al pueblo. El contexto une confianza y movimiento.',
        'Ao contemplar as pedras tiradas do Jordão, um aprendiz pergunta se o memorial é apenas uma lembrança privada da vitória ou uma escola para as próximas gerações.': 'Al contemplar las piedras tomadas del Jordán, un aprendiz pregunta si el memorial es solo un recuerdo privado de la victoria o una escuela para las próximas generaciones.',
        'Qual leitura preserva melhor a intenção do memorial?': '¿Qué lectura conserva mejor la intención del memorial?',
        'As pedras funcionam como um amuleto que garante que nenhuma nova travessia será difícil.': 'Las piedras funcionan como un amuleto que garantiza que ningún cruce futuro será difícil.',
        'O memorial conserva a ação de Deus para despertar perguntas e transmitir a história às futuras gerações.': 'El memorial conserva la acción de Dios para despertar preguntas y transmitir la historia a las futuras generaciones.',
        'As pedras celebram somente a habilidade de Josué e dispensam a memória da comunidade.': 'Las piedras celebran solamente la habilidad de Josué y prescinden de la memoria de la comunidad.',
        'O sinal pede que o povo fique preso ao passado e não interprete mais sua história.': 'La señal pide que el pueblo quede atrapado en el pasado y no vuelva a interpretar su historia.',
        'Memória que ensina a atravessar': 'Memoria que enseña a cruzar',
        'O memorial bíblico não é um objeto mágico nem uma nostalgia fechada: ele cria uma conversa entre gerações para que a travessia se torne testemunho e aprendizado.': 'El memorial bíblico no es un objeto mágico ni una nostalgia cerrada: crea una conversación entre generaciones para que el cruce se convierta en testimonio y aprendizaje.',
        'A leitura mais coerente entende as pedras como um sinal comunitário: elas preservam a travessia para que os filhos perguntem e a história do cuidado de Deus seja contada novamente.': 'La lectura más coherente entiende las piedras como una señal comunitaria: preservan el cruce para que los hijos pregunten y la historia del cuidado de Dios vuelva a contarse.',
        'Em Josué 4:1-7, as pedras são retiradas do Jordão depois da travessia e recebem uma finalidade explícita: quando os filhos perguntarem, os adultos contarão o que Deus fez. O contexto desloca o memorial do poder do objeto para a responsabilidade de lembrar e ensinar.': 'En Josué 4:1-7, las piedras se toman del Jordán después del cruce y reciben una finalidad explícita: cuando los hijos pregunten, los adultos contarán lo que Dios hizo. El contexto desplaza el memorial del poder del objeto hacia la responsabilidad de recordar y enseñar.',
        'Ao ler a carta aos exilados, um aprendiz pergunta se buscar a paz da cidade significa esquecer Jerusalém ou assumir uma responsabilidade enquanto a espera continua.': 'Al leer la carta a los exiliados, un aprendiz pregunta si buscar la paz de la ciudad significa olvidar Jerusalén o asumir una responsabilidad mientras continúa la espera.',
        'Qual leitura preserva melhor o sentido de Jeremias 29:7?': '¿Qué lectura conserva mejor el sentido de Jeremías 29:7?',
        'A comunidade deve buscar o bem da cidade onde vive, sem negar a dor do exílio nem abandonar a esperança do retorno.': 'La comunidad debe buscar el bien de la ciudad donde vive, sin negar el dolor del exilio ni abandonar la esperanza del regreso.',
        'Buscar a paz exige considerar o exílio encerrado e abandonar toda memória de Jerusalém.': 'Buscar la paz exige considerar terminado el exilio y abandonar toda memoria de Jerusalén.',
        'A orientação permite aceitar qualquer injustiça da cidade, pois a paz seria apenas silêncio e conformidade.': 'La orientación permite aceptar cualquier injusticia de la ciudad, porque la paz sería solo silencio y conformidad.',
        'O versículo promete que a espera terminará imediatamente assim que a comunidade começar a orar.': 'El versículo promete que la espera terminará inmediatamente en cuanto la comunidad comience a orar.',
        'Esperança responsável no exílio': 'Esperanza responsable en el exilio',
        'A esperança de Jeremias não é fuga nem conformidade cega: ela ensina a cuidar do lugar presente enquanto a comunidade mantém viva a memória e aguarda o futuro de Deus.': 'La esperanza de Jeremías no es huida ni conformidad ciega: enseña a cuidar el lugar presente mientras la comunidad mantiene viva la memoria y espera el futuro de Dios.',
        'A leitura mais coerente entende “procurai a paz da cidade” como um chamado ao bem comum durante a espera: os exilados podem florescer e servir sem apagar a ferida nem a esperança de retorno.': 'La lectura más coherente entiende «buscad la paz de la ciudad» como un llamado al bien común durante la espera: los exiliados pueden florecer y servir sin borrar la herida ni la esperanza de regresar.',
        'Jeremias 29:4-14 é uma carta dirigida aos exilados na Babilônia. O texto orienta famílias a construir uma vida possível, buscar a paz da cidade e orar por ela, mas também conserva a promessa de que Deus não abandonou seu povo. O contexto mantém juntas responsabilidade presente, memória e esperança.': 'Jeremías 29:4-14 es una carta dirigida a los exiliados en Babilonia. El texto orienta a las familias a construir una vida posible, buscar la paz de la ciudad y orar por ella, pero también conserva la promesa de que Dios no abandonó a su pueblo. El contexto mantiene unidas la responsabilidad presente, la memoria y la esperanza.'
    },
    en: {
        'Durante a cópia de Gênesis 12, um aprendiz observa que Abrão parte sem conhecer todo o destino e pergunta o que essa cena ensina sobre a fé.': 'While copying Genesis 12, an apprentice notices that Abram leaves without knowing the whole destination and asks what this scene teaches about faith.',
        'Qual leitura preserva melhor o sentido da passagem?': 'Which reading best preserves the meaning of the passage?',
        'A fé é uma viagem sem direção, porque Deus não oferece promessa alguma.': 'Faith is a journey without direction because God offers no promise.',
        'A fé responde ao chamado e caminha confiando numa promessa que ainda não está totalmente visível.': 'Faith answers the call and walks by trusting a promise that is not yet fully visible.',
        'A passagem ensina que obedecer exige abandonar todos os vínculos familiares para sempre.': 'The passage teaches that obedience requires abandoning every family bond forever.',
        'O chamado vale apenas como uma ordem antiga, sem relação com confiança e resposta hoje.': 'The call matters only as an ancient command, unrelated to trust and response today.',
        'Quando a fé dá o primeiro passo': 'When faith takes its first step',
        'Interpretar uma passagem é relacionar a ordem recebida à resposta concreta de Abrão: a fé não é desorientação nem isolamento, mas confiança que se põe a caminho.': 'Interpreting a passage means relating the received command to Abram’s concrete response: faith is neither disorientation nor isolation, but trust that sets out.',
        'A leitura mais coerente entende a fé como uma resposta confiante ao chamado: Abrão parte porque há uma promessa, mesmo que o caminho completo ainda não tenha sido mostrado.': 'The most coherent reading understands faith as a confident response to the call: Abram leaves because there is a promise, even though the whole path has not yet been shown.',
        'Em Gênesis 12:1-4, Deus ordena que Abrão saia de sua terra e, ao mesmo tempo, anuncia bênção e futuro. O movimento da passagem une chamado, promessa e partida; por isso, não se trata de caminhar sem direção, mas de confiar antes de possuir todas as respostas.': 'In Genesis 12:1-4, God commands Abram to leave his land and at the same time announces blessing and a future. The passage joins call, promise, and departure; this is not walking without direction, but trusting before having every answer.',
        'Ao copiar a cena do mar Vermelho, um aprendiz pergunta se o silêncio pedido por Moisés significa desistir de agir ou confiar diante do medo.': 'While copying the Red Sea scene, an apprentice asks whether Moses’ call for silence means giving up action or trusting in the face of fear.',
        'Qual leitura preserva melhor o ensinamento de Êxodo 14:14?': 'Which reading best preserves the teaching of Exodus 14:14?',
        'O povo deveria abandonar toda responsabilidade, porque a fé torna qualquer ação humana desnecessária.': 'The people should abandon all responsibility because faith makes human action unnecessary.',
        'Moisés convida o povo a reconhecer a ação de Deus e a atravessar com confiança, não a permanecer para sempre imóvel.': 'Moses invites the people to recognize God’s action and cross with trust, not remain still forever.',
        'O versículo promete que pessoas fiéis nunca mais enfrentarão ameaças ou situações assustadoras.': 'The verse promises that faithful people will never face threats or frightening situations again.',
        'A passagem ensina que o medo deve ser escondido e que perguntas em momentos de crise são sempre falta de fé.': 'The passage teaches that fear must be hidden and questions in a crisis are always a lack of faith.',
        'Silêncio que prepara a travessia': 'Silence that prepares the crossing',
        'A confiança diante do mar não elimina a travessia: ela interrompe o pânico para que o povo reconheça o cuidado de Deus e avance quando o caminho se abre.': 'Trust before the sea does not remove the crossing: it interrupts panic so the people can recognize God’s care and move when the way opens.',
        'A leitura mais coerente entende o silêncio como uma pausa de confiança diante do medo, que prepara Israel para seguir a orientação de Deus e atravessar.': 'The most coherent reading understands the silence as a pause of trust before fear, preparing Israel to follow God’s guidance and cross.',
        'Êxodo 14:10-16 mostra Israel encurralado, temeroso e questionando Moisés. A palavra “O Senhor pelejará por vós” não encerra a narrativa em passividade: logo depois, Moisés recebe a ordem de mandar o povo avançar. O contexto une confiança e movimento.': 'Exodus 14:10-16 shows Israel trapped, afraid, and questioning Moses. “The Lord will fight for you” does not end the story in passivity: soon afterward Moses is told to move the people forward. The context joins trust and movement.',
        'Ao contemplar as pedras tiradas do Jordão, um aprendiz pergunta se o memorial é apenas uma lembrança privada da vitória ou uma escola para as próximas gerações.': 'Looking at the stones taken from the Jordan, an apprentice asks whether the memorial is only a private memory of victory or a school for future generations.',
        'Qual leitura preserva melhor a intenção do memorial?': 'Which reading best preserves the memorial’s purpose?',
        'As pedras funcionam como um amuleto que garante que nenhuma nova travessia será difícil.': 'The stones work as an amulet guaranteeing that no future crossing will be difficult.',
        'O memorial conserva a ação de Deus para despertar perguntas e transmitir a história às futuras gerações.': 'The memorial preserves God’s action to awaken questions and pass the story on to future generations.',
        'As pedras celebram somente a habilidade de Josué e dispensam a memória da comunidade.': 'The stones celebrate only Joshua’s skill and remove the need for the community’s memory.',
        'O sinal pede que o povo fique preso ao passado e não interprete mais sua história.': 'The sign asks the people to remain trapped in the past and never interpret their story again.',
        'Memória que ensina a atravessar': 'Memory that teaches us to cross',
        'O memorial bíblico não é um objeto mágico nem uma nostalgia fechada: ele cria uma conversa entre gerações para que a travessia se torne testemunho e aprendizado.': 'The biblical memorial is neither a magical object nor closed nostalgia: it creates conversation between generations so the crossing becomes testimony and learning.',
        'A leitura mais coerente entende as pedras como um sinal comunitário: elas preservam a travessia para que os filhos perguntem e a história do cuidado de Deus seja contada novamente.': 'The most coherent reading understands the stones as a community sign: they preserve the crossing so children can ask and the story of God’s care can be told again.',
        'Em Josué 4:1-7, as pedras são retiradas do Jordão depois da travessia e recebem uma finalidade explícita: quando os filhos perguntarem, os adultos contarão o que Deus fez. O contexto desloca o memorial do poder do objeto para a responsabilidade de lembrar e ensinar.': 'In Joshua 4:1-7, the stones are taken from the Jordan after the crossing with an explicit purpose: when children ask, adults will tell what God did. The context shifts the memorial from the object’s power to the responsibility to remember and teach.',
        'Ao ler a carta aos exilados, um aprendiz pergunta se buscar a paz da cidade significa esquecer Jerusalém ou assumir uma responsabilidade enquanto a espera continua.': 'Reading the letter to the exiles, an apprentice asks whether seeking the city’s peace means forgetting Jerusalem or accepting responsibility while the waiting continues.',
        'Qual leitura preserva melhor o sentido de Jeremias 29:7?': 'Which reading best preserves the meaning of Jeremiah 29:7?',
        'A comunidade deve buscar o bem da cidade onde vive, sem negar a dor do exílio nem abandonar a esperança do retorno.': 'The community should seek the good of the city where it lives without denying exile’s pain or abandoning hope of return.',
        'Buscar a paz exige considerar o exílio encerrado e abandonar toda memória de Jerusalém.': 'Seeking peace requires treating exile as over and abandoning every memory of Jerusalem.',
        'A orientação permite aceitar qualquer injustiça da cidade, pois a paz seria apenas silêncio e conformidade.': 'The instruction allows accepting any injustice in the city because peace would mean only silence and conformity.',
        'O versículo promete que a espera terminará imediatamente assim que a comunidade começar a orar.': 'The verse promises that waiting will end immediately once the community begins to pray.',
        'Esperança responsável no exílio': 'Responsible hope in exile',
        'A esperança de Jeremias não é fuga nem conformidade cega: ela ensina a cuidar do lugar presente enquanto a comunidade mantém viva a memória e aguarda o futuro de Deus.': 'Jeremiah’s hope is neither escape nor blind conformity: it teaches care for the present place while the community keeps memory alive and awaits God’s future.',
        'A leitura mais coerente entende “procurai a paz da cidade” como um chamado ao bem comum durante a espera: os exilados podem florescer e servir sem apagar a ferida nem a esperança de retorno.': 'The most coherent reading understands “seek the peace of the city” as a call to the common good while waiting: exiles can flourish and serve without erasing the wound or hope of return.',
        'Jeremias 29:4-14 é uma carta dirigida aos exilados na Babilônia. O texto orienta famílias a construir uma vida possível, buscar a paz da cidade e orar por ela, mas também conserva a promessa de que Deus não abandonou seu povo. O contexto mantém juntas responsabilidade presente, memória e esperança.': 'Jeremiah 29:4-14 is a letter to exiles in Babylon. It guides families to build a possible life, seek the city’s peace, and pray for it, while preserving the promise that God has not abandoned his people. The context holds present responsibility, memory, and hope together.'
    },
    de: {
        'Durante a cópia de Gênesis 12, um aprendiz observa que Abrão parte sem conhecer todo o destino e pergunta o que essa cena ensina sobre a fé.': 'Während der Abschrift von Genesis 12 bemerkt ein Lehrling, dass Abram aufbricht, ohne das ganze Ziel zu kennen, und fragt, was diese Szene über den Glauben lehrt.',
        'Qual leitura preserva melhor o sentido da passagem?': 'Welche Lesart bewahrt den Sinn dieser Passage am besten?',
        'A fé é uma viagem sem direção, porque Deus não oferece promessa alguma.': 'Glaube ist eine Reise ohne Richtung, weil Gott kein Versprechen gibt.',
        'A fé responde ao chamado e caminha confiando numa promessa que ainda não está totalmente visível.': 'Glaube antwortet auf den Ruf und geht im Vertrauen auf ein Versprechen, das noch nicht vollständig sichtbar ist.',
        'A passagem ensina que obedecer exige abandonar todos os vínculos familiares para sempre.': 'Die Passage lehrt, dass Gehorsam verlangt, alle familiären Bindungen für immer aufzugeben.',
        'O chamado vale apenas como uma ordem antiga, sem relação com confiança e resposta hoje.': 'Der Ruf gilt nur als alter Befehl, ohne Bezug zu Vertrauen und Antwort heute.',
        'Quando a fé dá o primeiro passo': 'Wenn der Glaube den ersten Schritt tut',
        'Interpretar uma passagem é relacionar a ordem recebida à resposta concreta de Abrão: a fé não é desorientação nem isolamento, mas confiança que se põe a caminho.': 'Eine Passage auszulegen heißt, den empfangenen Auftrag mit Abrams konkreter Antwort zu verbinden: Glaube ist weder Orientierungslosigkeit noch Isolation, sondern Vertrauen, das sich auf den Weg macht.',
        'A leitura mais coerente entende a fé como uma resposta confiante ao chamado: Abrão parte porque há uma promessa, mesmo que o caminho completo ainda não tenha sido mostrado.': 'Die schlüssigste Lesart versteht den Glauben als vertrauensvolle Antwort auf den Ruf: Abram bricht auf, weil es ein Versprechen gibt, auch wenn der ganze Weg noch nicht gezeigt wurde.',
        'Em Gênesis 12:1-4, Deus ordena que Abrão saia de sua terra e, ao mesmo tempo, anuncia bênção e futuro. O movimento da passagem une chamado, promessa e partida; por isso, não se trata de caminhar sem direção, mas de confiar antes de possuir todas as respostas.': 'In Genesis 12,1–4 fordert Gott Abram auf, sein Land zu verlassen, und kündigt zugleich Segen und Zukunft an. Die Passage verbindet Ruf, Verheißung und Aufbruch; es geht nicht um einen Weg ohne Richtung, sondern um Vertrauen, bevor alle Antworten vorliegen.',
        'Ao copiar a cena do mar Vermelho, um aprendiz pergunta se o silêncio pedido por Moisés significa desistir de agir ou confiar diante do medo.': 'Beim Abschreiben der Szene am Roten Meer fragt ein Lehrling, ob Moses’ Bitte um Stille bedeutet, nicht mehr zu handeln oder angesichts der Angst zu vertrauen.',
        'Qual leitura preserva melhor o ensinamento de Êxodo 14:14?': 'Welche Lesart bewahrt die Lehre aus Exodus 14,14 am besten?',
        'O povo deveria abandonar toda responsabilidade, porque a fé torna qualquer ação humana desnecessária.': 'Das Volk sollte jede Verantwortung aufgeben, weil der Glaube menschliches Handeln überflüssig macht.',
        'Moisés convida o povo a reconhecer a ação de Deus e a atravessar com confiança, não a permanecer para sempre imóvel.': 'Mose lädt das Volk ein, Gottes Handeln zu erkennen und vertrauensvoll hinüberzugehen, statt für immer unbeweglich zu bleiben.',
        'O versículo promete que pessoas fiéis nunca mais enfrentarão ameaças ou situações assustadoras.': 'Der Vers verspricht, dass gläubige Menschen nie wieder Bedrohungen oder beängstigenden Situationen begegnen.',
        'A passagem ensina que o medo deve ser escondido e que perguntas em momentos de crise são sempre falta de fé.': 'Die Passage lehrt, dass Angst verborgen werden muss und Fragen in einer Krise immer ein Mangel an Glauben sind.',
        'Silêncio que prepara a travessia': 'Stille, die den Aufbruch vorbereitet',
        'A confiança diante do mar não elimina a travessia: ela interrompe o pânico para que o povo reconheça o cuidado de Deus e avance quando o caminho se abre.': 'Vertrauen vor dem Meer beseitigt den Weg nicht: Es unterbricht die Panik, damit das Volk Gottes Fürsorge erkennt und weitergeht, wenn sich der Weg öffnet.',
        'A leitura mais coerente entende o silêncio como uma pausa de confiança diante do medo, que prepara Israel para seguir a orientação de Deus e atravessar.': 'Die schlüssigste Lesart versteht die Stille als vertrauensvolle Pause angesichts der Angst, die Israel darauf vorbereitet, Gottes Führung zu folgen und hinüberzugehen.',
        'Êxodo 14:10-16 mostra Israel encurralado, temeroso e questionando Moisés. A palavra “O Senhor pelejará por vós” não encerra a narrativa em passividade: logo depois, Moisés recebe a ordem de mandar o povo avançar. O contexto une confiança e movimento.': 'Exodus 14,10–16 zeigt Israel in Bedrängnis, voller Angst und mit Fragen an Mose. „Der Herr wird für euch kämpfen“ beendet die Geschichte nicht in Passivität: Kurz darauf erhält Mose den Auftrag, das Volk weiterzuführen. Der Kontext verbindet Vertrauen und Bewegung.',
        'Ao contemplar as pedras tiradas do Jordão, um aprendiz pergunta se o memorial é apenas uma lembrança privada da vitória ou uma escola para as próximas gerações.': 'Beim Betrachten der Steine aus dem Jordan fragt ein Lehrling, ob das Denkmal nur eine private Erinnerung an den Sieg oder eine Schule für kommende Generationen ist.',
        'Qual leitura preserva melhor a intenção do memorial?': 'Welche Lesart bewahrt die Absicht des Denkmals am besten?',
        'As pedras funcionam como um amuleto que garante que nenhuma nova travessia será difícil.': 'Die Steine wirken wie ein Amulett, das garantiert, dass kein künftiger Übergang schwierig wird.',
        'O memorial conserva a ação de Deus para despertar perguntas e transmitir a história às futuras gerações.': 'Das Denkmal bewahrt Gottes Handeln, weckt Fragen und gibt die Geschichte an kommende Generationen weiter.',
        'As pedras celebram somente a habilidade de Josué e dispensam a memória da comunidade.': 'Die Steine feiern nur Josuas Fähigkeit und machen die Erinnerung der Gemeinschaft überflüssig.',
        'O sinal pede que o povo fique preso ao passado e não interprete mais sua história.': 'Das Zeichen verlangt, dass das Volk in der Vergangenheit gefangen bleibt und seine Geschichte nicht mehr deutet.',
        'Memória que ensina a atravessar': 'Erinnerung, die den Übergang lehrt',
        'O memorial bíblico não é um objeto mágico nem uma nostalgia fechada: ele cria uma conversa entre gerações para que a travessia se torne testemunho e aprendizado.': 'Das biblische Denkmal ist weder ein magischer Gegenstand noch verschlossene Nostalgie: Es schafft ein Gespräch zwischen Generationen, damit der Übergang zu Zeugnis und Lernen wird.',
        'A leitura mais coerente entende as pedras como um sinal comunitário: elas preservam a travessia para que os filhos perguntem e a história do cuidado de Deus seja contada novamente.': 'Die schlüssigste Lesart versteht die Steine als gemeinschaftliches Zeichen: Sie bewahren den Übergang, damit die Kinder fragen und die Geschichte von Gottes Fürsorge erneut erzählt wird.',
        'Em Josué 4:1-7, as pedras são retiradas do Jordão depois da travessia e recebem uma finalidade explícita: quando os filhos perguntarem, os adultos contarão o que Deus fez. O contexto desloca o memorial do poder do objeto para a responsabilidade de lembrar e ensinar.': 'In Josua 4,1–7 werden die Steine nach dem Übergang aus dem Jordan genommen und erhalten einen klaren Zweck: Wenn die Kinder fragen, erzählen die Erwachsenen, was Gott getan hat. Der Kontext verlagert das Denkmal von der Macht des Gegenstands zur Verantwortung, sich zu erinnern und zu lehren.',
        'Ao ler a carta aos exilados, um aprendiz pergunta se buscar a paz da cidade significa esquecer Jerusalém ou assumir uma responsabilidade enquanto a espera continua.': 'Beim Lesen des Briefes an die Verbannten fragt ein Lehrling, ob den Frieden der Stadt zu suchen bedeutet, Jerusalem zu vergessen oder während des Wartens Verantwortung zu übernehmen.',
        'Qual leitura preserva melhor o sentido de Jeremias 29:7?': 'Welche Lesart bewahrt den Sinn von Jeremia 29,7 am besten?',
        'A comunidade deve buscar o bem da cidade onde vive, sem negar a dor do exílio nem abandonar a esperança do retorno.': 'Die Gemeinschaft soll das Wohl der Stadt suchen, in der sie lebt, ohne den Schmerz des Exils zu verleugnen oder die Hoffnung auf Rückkehr aufzugeben.',
        'Buscar a paz exige considerar o exílio encerrado e abandonar toda memória de Jerusalém.': 'Den Frieden zu suchen verlangt, das Exil als beendet zu betrachten und jede Erinnerung an Jerusalem aufzugeben.',
        'A orientação permite aceitar qualquer injustiça da cidade, pois a paz seria apenas silêncio e conformidade.': 'Die Weisung erlaubt, jedes Unrecht der Stadt hinzunehmen, weil Frieden nur Schweigen und Anpassung bedeute.',
        'O versículo promete que a espera terminará imediatamente assim que a comunidade começar a orar.': 'Der Vers verspricht, dass das Warten sofort endet, sobald die Gemeinschaft zu beten beginnt.',
        'Esperança responsável no exílio': 'Verantwortliche Hoffnung im Exil',
        'A esperança de Jeremias não é fuga nem conformidade cega: ela ensina a cuidar do lugar presente enquanto a comunidade mantém viva a memória e aguarda o futuro de Deus.': 'Jeremias’ Hoffnung ist weder Flucht noch blinde Anpassung: Sie lehrt, den gegenwärtigen Ort zu pflegen, während die Gemeinschaft die Erinnerung lebendig hält und Gottes Zukunft erwartet.',
        'A leitura mais coerente entende “procurai a paz da cidade” como um chamado ao bem comum durante a espera: os exilados podem florescer e servir sem apagar a ferida nem a esperança de retorno.': 'Die schlüssigste Lesart versteht „Sucht den Frieden der Stadt“ als Ruf zum Gemeinwohl während des Wartens: Die Verbannten können aufblühen und dienen, ohne die Wunde oder die Hoffnung auf Rückkehr auszulöschen.',
        'Jeremias 29:4-14 é uma carta dirigida aos exilados na Babilônia. O texto orienta famílias a construir uma vida possível, buscar a paz da cidade e orar por ela, mas também conserva a promessa de que Deus não abandonou seu povo. O contexto mantém juntas responsabilidade presente, memória e esperança.': 'Jeremia 29,4–14 ist ein Brief an die Verbannten in Babylon. Der Text weist Familien an, ein mögliches Leben aufzubauen, den Frieden der Stadt zu suchen und für sie zu beten, und bewahrt zugleich die Zusage, dass Gott sein Volk nicht verlassen hat. Der Kontext hält gegenwärtige Verantwortung, Erinnerung und Hoffnung zusammen.'
    },
    fr: {
        'Durante a cópia de Gênesis 12, um aprendiz observa que Abrão parte sem conhecer todo o destino e pergunta o que essa cena ensina sobre a fé.': 'En copiant Genèse 12, un apprenti remarque qu’Abram part sans connaître toute sa destination et demande ce que cette scène enseigne sur la foi.',
        'Qual leitura preserva melhor o sentido da passagem?': 'Quelle lecture préserve le mieux le sens du passage ?',
        'A fé é uma viagem sem direção, porque Deus não oferece promessa alguma.': 'La foi est un voyage sans direction, car Dieu ne donne aucune promesse.',
        'A fé responde ao chamado e caminha confiando numa promessa que ainda não está totalmente visível.': 'La foi répond à l’appel et avance en faisant confiance à une promesse qui n’est pas encore pleinement visible.',
        'A passagem ensina que obedecer exige abandonar todos os vínculos familiares para sempre.': 'Le passage enseigne qu’obéir exige d’abandonner pour toujours tous les liens familiaux.',
        'O chamado vale apenas como uma ordem antiga, sem relação com confiança e resposta hoje.': 'L’appel ne serait qu’un ordre ancien, sans lien avec la confiance et la réponse d’aujourd’hui.',
        'Quando a fé dá o primeiro passo': 'Quand la foi fait le premier pas',
        'Ao copiar a cena do mar Vermelho, um aprendiz pergunta se o silêncio pedido por Moisés significa desistir de agir ou confiar diante do medo.': 'En copiant la scène de la mer Rouge, un apprenti demande si le silence demandé par Moïse signifie renoncer à agir ou faire confiance face à la peur.',
        'Qual leitura preserva melhor o ensinamento de Êxodo 14:14?': 'Quelle lecture préserve le mieux l’enseignement d’Exode 14,14 ?',
        'O povo deveria abandonar toda responsabilidade, porque a fé torna qualquer ação humana desnecessária.': 'Le peuple devrait abandonner toute responsabilité, car la foi rend toute action humaine inutile.',
        'Moisés convida o povo a reconhecer a ação de Deus e a atravessar com confiança, não a permanecer para sempre imóvel.': 'Moïse invite le peuple à reconnaître l’action de Dieu et à traverser avec confiance, non à rester immobile pour toujours.',
        'O versículo promete que pessoas fiéis nunca mais enfrentarão ameaças ou situações assustadoras.': 'Le verset promet que les personnes fidèles ne connaîtront plus jamais de menaces ni de situations effrayantes.',
        'A passagem ensina que o medo deve ser escondido e que perguntas em momentos de crise são sempre falta de fé.': 'Le passage enseigne qu’il faut cacher la peur et que les questions en temps de crise sont toujours un manque de foi.',
        'Silêncio que prepara a travessia': 'Le silence qui prépare la traversée',
        'Ao contemplar as pedras tiradas do Jordão, um aprendiz pergunta se o memorial é apenas uma lembrança privada da vitória ou uma escola para as próximas gerações.': 'En contemplant les pierres prises dans le Jourdain, un apprenti demande si le mémorial est seulement un souvenir privé de la victoire ou une école pour les générations futures.',
        'Qual leitura preserva melhor a intenção do memorial?': 'Quelle lecture préserve le mieux l’intention du mémorial ?',
        'As pedras funcionam como um amuleto que garante que nenhuma nova travessia será difícil.': 'Les pierres seraient une amulette garantissant qu’aucune traversée future ne sera difficile.',
        'O memorial conserva a ação de Deus para despertar perguntas e transmitir a história às futuras gerações.': 'Le mémorial conserve l’action de Dieu pour éveiller les questions et transmettre l’histoire aux générations futures.',
        'As pedras celebram somente a habilidade de Josué e dispensam a memória da comunidade.': 'Les pierres célèbrent seulement l’habileté de Josué et rendent inutile la mémoire de la communauté.',
        'O sinal pede que o povo fique preso ao passado e não interprete mais sua história.': 'Le signe demande au peuple de rester prisonnier du passé et de ne plus interpréter son histoire.',
        'Memória que ensina a atravessar': 'Une mémoire qui apprend à traverser',
        'Ao ler a carta aos exilados, um aprendiz pergunta se buscar a paz da cidade significa esquecer Jerusalém ou assumir uma responsabilidade enquanto a espera continua.': 'En lisant la lettre aux exilés, un apprenti demande si chercher la paix de la ville signifie oublier Jérusalem ou assumer une responsabilité pendant l’attente.',
        'Qual leitura preserva melhor o sentido de Jeremias 29:7?': 'Quelle lecture préserve le mieux le sens de Jérémie 29,7 ?',
        'A comunidade deve buscar o bem da cidade onde vive, sem negar a dor do exílio nem abandonar a esperança do retorno.': 'La communauté doit chercher le bien de la ville où elle vit, sans nier la douleur de l’exil ni abandonner l’espérance du retour.',
        'Buscar a paz exige considerar o exílio encerrado e abandonar toda memória de Jerusalém.': 'Chercher la paix exigerait de considérer l’exil comme terminé et d’abandonner tout souvenir de Jérusalem.',
        'A orientação permite aceitar qualquer injustiça da cidade, pois a paz seria apenas silêncio e conformidade.': 'L’orientation permettrait d’accepter toute injustice, puisque la paix ne serait que silence et conformité.',
        'O versículo promete que a espera terminará imediatamente assim que a comunidade começar a orar.': 'Le verset promet que l’attente se terminera immédiatement dès que la communauté commencera à prier.',
        'Esperança responsável no exílio': 'Une espérance responsable dans l’exil'
    },
    ro: {
        'Durante a cópia de Gênesis 12, um aprendiz observa que Abrão parte sem conhecer todo o destino e pergunta o que essa cena ensina sobre a fé.': 'În timp ce copiază Geneza 12, un ucenic observă că Avram pleacă fără să cunoască întreaga destinație și întreabă ce învață această scenă despre credință.',
        'Qual leitura preserva melhor o sentido da passagem?': 'Care interpretare păstrează cel mai bine sensul pasajului?',
        'A fé é uma viagem sem direção, porque Deus não oferece promessa alguma.': 'Credința este o călătorie fără direcție, deoarece Dumnezeu nu oferă nicio promisiune.',
        'A fé responde ao chamado e caminha confiando numa promessa que ainda não está totalmente visível.': 'Credința răspunde chemării și merge încrezătoare într-o promisiune care încă nu este pe deplin vizibilă.',
        'A passagem ensina que obedecer exige abandonar todos os vínculos familiares para sempre.': 'Pasajul învață că ascultarea cere abandonarea pentru totdeauna a tuturor legăturilor de familie.',
        'O chamado vale apenas como uma ordem antiga, sem relação com confiança e resposta hoje.': 'Chemarea ar fi doar o poruncă veche, fără legătură cu încrederea și răspunsul de astăzi.',
        'Quando a fé dá o primeiro passo': 'Când credința face primul pas',
        'Ao copiar a cena do mar Vermelho, um aprendiz pergunta se o silêncio pedido por Moisés significa desistir de agir ou confiar diante do medo.': 'În timp ce copiază scena Mării Roșii, un ucenic întreabă dacă tăcerea cerută de Moise înseamnă să renunțe la acțiune sau să aibă încredere în fața fricii.',
        'Qual leitura preserva melhor o ensinamento de Êxodo 14:14?': 'Care interpretare păstrează cel mai bine învățătura din Exodul 14:14?',
        'O povo deveria abandonar toda responsabilidade, porque a fé torna qualquer ação humana desnecessária.': 'Poporul ar trebui să renunțe la orice responsabilitate, deoarece credința face inutilă orice acțiune omenească.',
        'Moisés convida o povo a reconhecer a ação de Deus e a atravessar com confiança, não a permanecer para sempre imóvel.': 'Moise invită poporul să recunoască lucrarea lui Dumnezeu și să treacă prin încercare cu încredere, nu să rămână nemișcat pentru totdeauna.',
        'O versículo promete que pessoas fiéis nunca mais enfrentarão ameaças ou situações assustadoras.': 'Versetul promite că oamenii credincioși nu vor mai întâlni niciodată amenințări sau situații înfricoșătoare.',
        'A passagem ensina que o medo deve ser escondido e que perguntas em momentos de crise são sempre falta de fé.': 'Pasajul învață că frica trebuie ascunsă și că întrebările în criză sunt întotdeauna lipsă de credință.',
        'Silêncio que prepara a travessia': 'Tăcerea care pregătește trecerea',
        'Ao contemplar as pedras tiradas do Jordão, um aprendiz pergunta se o memorial é apenas uma lembrança privada da vitória ou uma escola para as próximas gerações.': 'Privind pietrele luate din Iordan, un ucenic întreabă dacă memorialul este doar o amintire privată a victoriei sau o școală pentru generațiile următoare.',
        'Qual leitura preserva melhor a intenção do memorial?': 'Care interpretare păstrează cel mai bine intenția memorialului?',
        'As pedras funcionam como um amuleto que garante que nenhuma nova travessia será difícil.': 'Pietrele ar funcționa ca un talisman care garantează că nicio trecere viitoare nu va fi dificilă.',
        'O memorial conserva a ação de Deus para despertar perguntas e transmitir a história às futuras gerações.': 'Memorialul păstrează lucrarea lui Dumnezeu pentru a trezi întrebări și a transmite istoria generațiilor viitoare.',
        'As pedras celebram somente a habilidade de Josué e dispensam a memória da comunidade.': 'Pietrele celebrează doar priceperea lui Iosua și elimină memoria comunității.',
        'O sinal pede que o povo fique preso ao passado e não interprete mais sua história.': 'Semnul cere poporului să rămână prins în trecut și să nu-și mai interpreteze istoria.',
        'Memória que ensina a atravessar': 'Memoria care învață trecerea',
        'Ao ler a carta aos exilados, um aprendiz pergunta se buscar a paz da cidade significa esquecer Jerusalém ou assumir uma responsabilidade enquanto a espera continua.': 'Citind scrisoarea către exilați, un ucenic întreabă dacă a căuta pacea cetății înseamnă să uite Ierusalimul sau să-și asume responsabilitatea în timp ce așteptarea continuă.',
        'Qual leitura preserva melhor o sentido de Jeremias 29:7?': 'Care interpretare păstrează cel mai bine sensul din Ieremia 29:7?',
        'A comunidade deve buscar o bem da cidade onde vive, sem negar a dor do exílio nem abandonar a esperança do retorno.': 'Comunitatea trebuie să caute binele cetății în care trăiește, fără să nege durerea exilului sau să abandoneze speranța întoarcerii.',
        'Buscar a paz exige considerar o exílio encerrado e abandonar toda memória de Jerusalém.': 'A căuta pacea ar cere să considere exilul încheiat și să abandoneze orice amintire a Ierusalimului.',
        'A orientação permite aceitar qualquer injustiça da cidade, pois a paz seria apenas silêncio e conformidade.': 'Îndrumarea ar permite acceptarea oricărei nedreptăți, deoarece pacea ar însemna doar tăcere și conformare.',
        'O versículo promete que a espera terminará imediatamente assim que a comunidade começar a orar.': 'Versetul promite că așteptarea se va încheia imediat ce comunitatea începe să se roage.',
        'Esperança responsável no exílio': 'Speranță responsabilă în exil'
    },
    ru: {
        'Durante a cópia de Gênesis 12, um aprendiz observa que Abrão parte sem conhecer todo o destino e pergunta o que essa cena ensina sobre a fé.': 'Переписывая Бытие 12, ученик замечает, что Аврам уходит, не зная всего пути, и спрашивает, чему эта сцена учит о вере.',
        'Qual leitura preserva melhor o sentido da passagem?': 'Какое прочтение лучше всего сохраняет смысл отрывка?',
        'A fé é uma viagem sem direção, porque Deus não oferece promessa alguma.': 'Вера — это путь без направления, потому что Бог не даёт обещания.',
        'A fé responde ao chamado e caminha confiando numa promessa que ainda não está totalmente visível.': 'Вера отвечает на призыв и идёт, доверяя обещанию, которое ещё не видно полностью.',
        'A passagem ensina que obedecer exige abandonar todos os vínculos familiares para sempre.': 'Отрывок учит, что послушание требует навсегда оставить все семейные связи.',
        'O chamado vale apenas como uma ordem antiga, sem relação com confiança e resposta hoje.': 'Призыв имеет значение лишь как древняя заповедь, не связанная с доверием и сегодняшним ответом.',
        'Quando a fé dá o primeiro passo': 'Когда вера делает первый шаг',
        'Ao copiar a cena do mar Vermelho, um aprendiz pergunta se o silêncio pedido por Moisés significa desistir de agir ou confiar diante do medo.': 'Переписывая сцену Красного моря, ученик спрашивает, означает ли просьба Моисея о тишине отказ от действия или доверие перед лицом страха.',
        'Qual leitura preserva melhor o ensinamento de Êxodo 14:14?': 'Какое прочтение лучше всего сохраняет наставление Исхода 14:14?',
        'O povo deveria abandonar toda responsabilidade, porque a fé torna qualquer ação humana desnecessária.': 'Народ должен отказаться от всякой ответственности, потому что вера делает человеческие действия ненужными.',
        'Moisés convida o povo a reconhecer a ação de Deus e a atravessar com confiança, não a permanecer para sempre imóvel.': 'Моисей призывает народ признать действие Бога и перейти с доверием, а не оставаться неподвижным навсегда.',
        'O versículo promete que pessoas fiéis nunca mais enfrentarão ameaças ou situações assustadoras.': 'Стих обещает, что верные люди больше никогда не встретятся с угрозами или страшными ситуациями.',
        'A passagem ensina que o medo deve ser escondido e que perguntas em momentos de crise são sempre falta de fé.': 'Отрывок учит скрывать страх и считать вопросы во время кризиса недостатком веры.',
        'Silêncio que prepara a travessia': 'Тишина, готовящая к переходу',
        'Ao contemplar as pedras tiradas do Jordão, um aprendiz pergunta se o memorial é apenas uma lembrança privada da vitória ou uma escola para as próximas gerações.': 'Рассматривая камни, взятые из Иордана, ученик спрашивает, является ли памятник лишь личной памятью о победе или школой для будущих поколений.',
        'Qual leitura preserva melhor a intenção do memorial?': 'Какое прочтение лучше всего сохраняет назначение памятника?',
        'As pedras funcionam como um amuleto que garante que nenhuma nova travessia será difícil.': 'Камни действуют как амулет, гарантирующий, что ни один будущий переход не будет трудным.',
        'O memorial conserva a ação de Deus para despertar perguntas e transmitir a história às futuras gerações.': 'Памятник сохраняет действие Бога, пробуждает вопросы и передаёт историю будущим поколениям.',
        'As pedras celebram somente a habilidade de Josué e dispensam a memória da comunidade.': 'Камни прославляют только умение Иисуса Навина и отменяют память общины.',
        'O sinal pede que o povo fique preso ao passado e não interprete mais sua história.': 'Знак требует, чтобы народ застрял в прошлом и больше не истолковывал свою историю.',
        'Memória que ensina a atravessar': 'Память, которая учит переходить',
        'Ao ler a carta aos exilados, um aprendiz pergunta se buscar a paz da cidade significa esquecer Jerusalém ou assumir uma responsabilidade enquanto a espera continua.': 'Читая письмо изгнанникам, ученик спрашивает, означает ли искать мир города забыть Иерусалим или принять ответственность во время ожидания.',
        'Qual leitura preserva melhor o sentido de Jeremias 29:7?': 'Какое прочтение лучше всего сохраняет смысл Иеремии 29:7?',
        'A comunidade deve buscar o bem da cidade onde vive, sem negar a dor do exílio nem abandonar a esperança do retorno.': 'Община должна искать блага города, где живёт, не отрицая боль изгнания и не оставляя надежду на возвращение.',
        'Buscar a paz exige considerar o exílio encerrado e abandonar toda memória de Jerusalém.': 'Искать мира значит считать изгнание завершённым и оставить всякую память об Иерусалиме.',
        'A orientação permite aceitar qualquer injustiça da cidade, pois a paz seria apenas silêncio e conformidade.': 'Наставление позволяет принять любую несправедливость города, потому что мир — это лишь молчание и покорность.',
        'O versículo promete que a espera terminará imediatamente assim que a comunidade começar a orar.': 'Стих обещает, что ожидание немедленно закончится, как только община начнёт молиться.',
        'Esperança responsável no exílio': 'Ответственная надежда в изгнании'
    }
};

