const dictionaryCache = new Map();
function translateTextValue(value, language) {
    const source = String(value ?? '');
    const trimmed = source.trim().replace(/\s+/g, ' ');
    if (!trimmed) return source;
    const dictionary = dictionaryCache.get(language) || {
        ...(PHASE_TITLE_TRANSLATIONS[language] || {}),
        ...(TRANSLATIONS[language] || {}),
        ...(START_STATE_TRANSLATIONS[language] || {}),
        ...(SHARED_CHALLENGE_TRANSLATIONS[language] || {}),
        ...(CHALLENGE_CONTENT_TRANSLATIONS[language] || {}),
        ...(MANUSCRIPT_GALLERY_TRANSLATIONS[language] || {}),
        ...(ADDITIONAL_UI_TRANSLATIONS[language] || {}),
        ...(ENTRY_SCREEN_TRANSLATIONS[language] || {}),
        ...(SCRIPTORIUM_INTENTION_TRANSLATIONS[language] || {}),
        ...(DEEP_RUNTIME_TRANSLATIONS[language] || {}),
        ...(MICRO_RUNTIME_TRANSLATIONS[language] || {}),
        ...(CONTINUATION_UI_TRANSLATIONS[language] || {}),
        ...(INLINE_UI_TRANSLATIONS[language] || {}),
        ...(RUNTIME_UI_TRANSLATIONS[language] || {}),
        ...(CHALLENGE_UI_TRANSLATIONS[language] || {}),
        ...(FEEDBACK_TRANSLATIONS[language] || {}),
        ...(EDUCATIONAL_FEEDBACK_TRANSLATIONS[language] || {}),
        ...(LATER_UI_TRANSLATIONS[language] || {}),
        ...(INTERPRETATION_EVIDENCE_TRANSLATIONS[language] || {}),
        ...(chapterTranslations[language] || {}),
        ...(language === 'de' ? coreTranslationsDe : {})
    };
    dictionaryCache.set(language, dictionary);
    const exact = dictionary[trimmed];
    if (exact) return preserveWhitespace(source, exact);

    const phaseTitles = PHASE_TITLE_TRANSLATIONS[language] || {};
    const dynamicLabels = {
        pt: {
            recovery: 'Abrir sessão de recuperação',
            recoveryPassage: 'passagem',
            recoveryPassages: 'passagens',
            resume: 'para retomar',
            intention: 'Intenção já inscrita',
            achievement: 'Conquista mais recente',
            visitOne: 'visita concluída foi inscrita no caminho.',
            visitMany: 'visitas concluídas foram inscritas no caminho.',
            challenge: 'Desafio',
            currentChallenge: 'Desafio atual',
            passage: 'Passagem'
        },
        es: {
            recovery: 'Abrir sesión de recuperación', recoveryPassage: 'pasaje', recoveryPassages: 'pasajes', resume: 'para retomar', intention: 'Intención ya registrada', achievement: 'Logro más reciente', visitOne: 'visita completada fue registrada en el camino.', visitMany: 'visitas completadas fueron registradas en el camino.', challenge: 'Desafío', currentChallenge: 'Desafío actual', passage: 'Pasaje'
        },
        en: {
            recovery: 'Open recovery session', recoveryPassage: 'passage', recoveryPassages: 'passages', resume: 'to resume', intention: 'Intention already recorded', achievement: 'Most recent achievement', visitOne: 'completed visit was recorded along the path.', visitMany: 'completed visits were recorded along the path.', challenge: 'Challenge', currentChallenge: 'Current challenge', passage: 'Passage'
        },
        de: {
            recovery: 'Wiederholungssitzung öffnen', recoveryPassage: 'Passage', recoveryPassages: 'Passagen', resume: 'zum Fortsetzen', intention: 'Absicht bereits eingetragen', achievement: 'Neueste Errungenschaft', visitOne: 'abgeschlossener Besuch wurde auf dem Weg eingetragen.', visitMany: 'abgeschlossene Besuche wurden auf dem Weg eingetragen.', challenge: 'Herausforderung', currentChallenge: 'Aktuelle Herausforderung', passage: 'Passage'
        },
        fr: {
            recovery: 'Ouvrir la session de reprise', recoveryPassage: 'passage', recoveryPassages: 'passages', resume: 'à reprendre', intention: 'Intention déjà inscrite', achievement: 'Réussite la plus récente', visitOne: 'visite terminée a été inscrite sur le parcours.', visitMany: 'visites terminées ont été inscrites sur le parcours.', challenge: 'Défi', currentChallenge: 'Défi actuel', passage: 'Passage'
        },
        ro: {
            recovery: 'Deschide sesiunea de recuperare', recoveryPassage: 'pasaj', recoveryPassages: 'pasaje', resume: 'pentru reluare', intention: 'Intenție deja înscrisă', achievement: 'Cea mai recentă reușită', visitOne: 'vizită finalizată a fost înscrisă pe cale.', visitMany: 'vizite finalizate au fost înscrise pe cale.', challenge: 'Provocare', currentChallenge: 'Provocarea actuală', passage: 'Pasaj'
        },
        ru: {
            recovery: 'Открыть сеанс восстановления', recoveryPassage: 'отрывок', recoveryPassages: 'отрывка', resume: 'для продолжения', intention: 'Намерение уже записано', achievement: 'Последнее достижение', visitOne: 'завершённое посещение внесено на путь.', visitMany: 'завершённых посещения внесены на путь.', challenge: 'Испытание', currentChallenge: 'Текущее испытание', passage: 'Отрывок'
        }
    }[language] || null;
    const dynamicFallbacks = {
        pt: { currentPhase: 'Fase atual:', savedPage: 'Página guardada:', nextVisit: 'A próxima visita pode começar no ponto que pede cuidado, sem apressar o que ainda está amadurecendo.' },
        es: { currentPhase: 'Fase actual:', savedPage: 'Página guardada:', nextVisit: 'La próxima visita puede comenzar en el punto que pide cuidado, sin apresurar lo que aún está madurando.' },
        en: { currentPhase: 'Current phase:', savedPage: 'Saved page:', nextVisit: 'The next visit can begin at the point that needs care, without rushing what is still maturing.' },
        de: { currentPhase: 'Aktuelle Phase:', savedPage: 'Gespeicherte Seite:', nextVisit: 'Der nächste Besuch kann an dem Punkt beginnen, der Aufmerksamkeit braucht, ohne zu überstürzen, was noch reift.' },
        fr: { currentPhase: 'Phase actuelle :', savedPage: 'Page enregistrée :', nextVisit: 'La prochaine visite peut commencer au point qui demande de l’attention, sans précipiter ce qui mûrit encore.' },
        ro: { currentPhase: 'Etapa actuală:', savedPage: 'Pagina salvată:', nextVisit: 'Următoarea vizită poate începe în punctul care cere atenție, fără a grăbi ceea ce încă se maturizează.' },
        ru: { currentPhase: 'Текущий этап:', savedPage: 'Сохранённая страница:', nextVisit: 'Следующее посещение может начаться с того, что требует внимания, не торопя то, что ещё созревает.' }
    }[language] || {};
    const phaseTitleMatch = trimmed.match(/^Fase ([1-4]) · (.+)$/);
    const phaseWord = {
        pt: 'Fase', es: 'Fase', en: 'Phase', de: 'Phase', fr: 'Phase', ro: 'Etapă', ru: 'Этап'
    }[language] || 'Fase';
    if (phaseTitleMatch && phaseTitles[phaseTitleMatch[2]]) {
        return preserveWhitespace(source, `${phaseWord} ${phaseTitleMatch[1]} · ${phaseTitles[phaseTitleMatch[2]]}`);
    }

    const dynamicPatterns = [
        [/^Fase ([IVX1-4]+) · tema$/, (match) => `${phaseWord} ${match[1]} · ${{pt:'tema',es:'tema',en:'theme',de:'Thema',fr:'thème',ro:'temă',ru:'тема'}[language]}`],
        [/^Abrir o manuscrito da Fase ([1-4])$/, (match) => `${{pt:'Abrir o manuscrito da Fase',es:'Abrir el manuscrito de la fase',en:'Open the manuscript for Phase',de:'Manuskript öffnen · Phase',fr:'Ouvrir le manuscrit de la phase',ro:'Deschide manuscrisul etapei',ru:'Открыть рукопись этапа'}[language]} ${match[1]}`],
        [/^Contemplar o registro da Fase ([1-4])$/, (match) => `${{pt:'Contemplar o registro da Fase',es:'Contemplar el registro de la fase',en:'Read the record for Phase',de:'Eintrag betrachten · Phase',fr:'Contempler le registre de la phase',ro:'Contemplă însemnarea etapei',ru:'Посмотреть запись этапа'}[language]} ${match[1]}`],
        [/^Gênesis ([\d:–—,; .-]+)$/, (match) => `${{pt:'Gênesis',es:'Génesis',en:'Genesis',de:'Genesis',fr:'Genèse',ro:'Geneza',ru:'Бытие'}[language]} ${match[1]}`],
        [/^Fase atual: (.+)$/, (match) => `${dictionary['Fase atual:'] || dynamicFallbacks.currentPhase} ${translateTextValue(match[1], language)}`],
        [/^Página guardada: (.+)$/, (match) => `${dictionary['Página guardada:'] || dynamicFallbacks.savedPage} ${dictionary[match[1]] || translateTextValue(match[1], language)}`],
        [/^Abrir sessão de recuperação · (\d+) (passagem|passagens) para retomar$/, (match) => `${dynamicLabels?.recovery || 'Abrir sessão de recuperação'} · ${match[1]} ${match[1] === '1' ? dynamicLabels?.recoveryPassage : dynamicLabels?.recoveryPassages} ${dynamicLabels?.resume || 'para retomar'}`],
        [/^Intenção já inscrita · (Passagem frágil|Recomendação da agenda|Leitura livre) · (.+)\.$/, (match) => `${dynamicLabels?.intention || 'Intenção já inscrita'} · ${translateTextValue(match[1], language)} · ${match[2]}.`],
        [/^Conquista mais recente · (.+)$/, (match) => `${dynamicLabels?.achievement || 'Conquista mais recente'} · ${translateTextValue(match[1], language)}`],
        [/^(.+) A próxima visita pode começar no ponto que pede cuidado, sem apressar o que ainda está amadurecendo\.$/, (match) => `${translateTextValue(match[1], language)} ${dictionary['A próxima visita pode começar no ponto que pede cuidado, sem apressar o que ainda está amadurecendo.'] || dynamicFallbacks.nextVisit}`],
        [/^(\d+) (visita concluída foi|visitas concluídas foram) inscrita(s?) no caminho\.$/, (match) => `${match[1]} ${match[1] === '1' ? dynamicLabels?.visitOne : dynamicLabels?.visitMany}`],
        [/^Desafio (\d+) de (\d+)$/, (match) => `${dynamicLabels?.challenge || 'Desafio'} ${match[1]} de ${match[2]}`],
        [/^Desafio atual · (\d+) de (\d+)$/, (match) => `${dynamicLabels?.currentChallenge || 'Desafio atual'} · ${match[1]} de ${match[2]}`],
        [/^Passagem (\d+) de (\d+)$/, (match) => `${dynamicLabels?.passage || 'Passagem'} ${match[1]} de ${match[2]}`],
        [/^(\d+) de (\d+) · (\d+)% · (.+)$/, (match) => `${match[1]} de ${match[2]} · ${match[3]}% · ${match[4]}`]
    ];
    for (const [pattern, replacement] of dynamicPatterns) {
        const match = trimmed.match(pattern);
        if (match) return preserveWhitespace(source, replacement(match));
    }
    const inlineFragments = Object.entries(INLINE_UI_TRANSLATIONS[language] || {})
        .sort(([first], [second]) => second.length - first.length);
    let fragmentResult = trimmed;
    inlineFragments.forEach(([from, to]) => {
        if (fragmentResult.includes(from)) fragmentResult = fragmentResult.split(from).join(to);
    });
    return fragmentResult === trimmed ? source : preserveWhitespace(source, fragmentResult);
}

const PROTECTED_SELECTOR = [
    '.challenge-choice',
    '.review-option',
    '.order-item',
    '.challenge-question',
    '.challenge-verse',
    '.verse-input',
    '[data-idx]',
    '[data-memory-choice]',
    '[data-contextual-recovery-decision]',
    '[data-contextual-set-answer]',
    '[data-interpretation-confidence]',
    '[data-interpretation-attitude]',
    '.interpretation-evidence-clue',
    '[data-practice-comparison-exercise-choice]',
    '[data-practice-comparison-continuity-choice]',
    '[data-understanding-gap-choice]',
    '[data-understanding-gap-practice-choice]',
    '[data-understanding-gap-sequence-choice]',
    '[data-contextual-synthesis-arrival-choice]',
    '[data-vocabulary-association-choice]'
].join(',');

function isProtectedTextNode(node) {
    const parent = node.parentElement;
    return Boolean(parent?.closest(PROTECTED_SELECTOR));
}

function translateAttributes(element, language) {
    if (!(element instanceof Element) || element.matches(PROTECTED_SELECTOR)) return;
    ['title', 'aria-label', 'placeholder'].forEach(attribute => {
        if (!element.hasAttribute(attribute)) return;
        const source = element.getAttribute(attribute);
        const translated = translateTextValue(source, language);
        if (translated !== source) element.setAttribute(attribute, translated);
    });
}

const translatedTextSources = new WeakMap();
function translateRoot(root, language) {
    if (!(root instanceof Node)) return;
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    const textNodes = root.nodeType === Node.TEXT_NODE ? [root] : [];
    let node;
    while ((node = walker.nextNode())) textNodes.push(node);
    textNodes.forEach(textNode => {
        if (isProtectedTextNode(textNode)) return;
        if (textNode.parentElement?.closest('script, style, textarea, [contenteditable="true"]')) return;
        const previous = translatedTextSources.get(textNode);
        const source = previous?.translated === textNode.nodeValue ? previous.source : textNode.nodeValue;
        const translated = translateTextValue(source, language);
        translatedTextSources.set(textNode, { source, translated });
        if (translated !== textNode.nodeValue) textNode.nodeValue = translated;
    });
    if (root instanceof Element) {
        translateAttributes(root, language);
        root.querySelectorAll('*').forEach(element => translateAttributes(element, language));
    }
}

class GameI18n {
    constructor() {
        this.language = getInitialLanguage();
        this.observer = null;
    }

    t(value) {
        return translateTextValue(value, this.language);
    }

    apply(root = document.body) {
        if (root) translateRoot(root, this.language);
        document.documentElement.lang = LANGUAGE_TAGS[this.language];
        document.title = this.t('Guardião da Palavra') + ': ' + this.t('O Desafio dos Pergaminhos');
        const selector = document.getElementById('language-select');
        if (selector) selector.value = this.language;
    }

    setLanguage(value, { reload = true } = {}) {
        const nextLanguage = normalizeLanguage(value);
        try {
            localStorage.setItem(LANGUAGE_STORAGE_KEY, nextLanguage);
        } catch (error) {
            // A troca ainda funciona nesta sessão.
        }
        const url = new URL(window.location.href);
        url.searchParams.set('lang', nextLanguage);
        window.history.replaceState({}, '', url);
        this.language = nextLanguage;
        this.apply();
        if (reload) window.location.reload();
    }

    start() {
        const selector = document.getElementById('language-select');
        selector?.addEventListener('change', event => this.setLanguage(event.target.value));
        this.apply();
        if (!document.body) return;
        this.observer = new MutationObserver(mutations => {
            mutations.forEach(mutation => {
                mutation.addedNodes.forEach(addedNode => this.apply(addedNode));
                if (mutation.type === 'characterData' && mutation.target.parentElement) {
                    this.apply(mutation.target.parentElement);
                }
            });
        });
        this.observer.observe(document.body, { childList: true, characterData: true, subtree: true });
    }
}

export const i18n = new GameI18n();
export const supportedLanguages = [...SUPPORTED_LANGUAGES];
export const normalizeLocale = normalizeLanguage;

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => i18n.start(), { once: true });
} else {
    i18n.start();
}
